package br.com.mathinclui.auth.token;
import br.com.mathinclui.auth.api.AuthProblemException; import br.com.mathinclui.auth.security.*; import org.junit.jupiter.api.Test; import java.time.*; import java.util.Optional; import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class RefreshTokenServiceTest { private static final Instant NOW=Instant.parse("2026-10-15T18:00:00Z"); private final Clock clock=Clock.fixed(NOW,ZoneOffset.UTC); @Test void shouldRejectRefreshTokenWithoutActiveSession(){var jwt=mock(JwtTokenService.class);var repository=mock(RefreshTokenRepository.class);when(jwt.parseRefresh("token")).thenReturn(claims());when(repository.findByJti("jti-1")).thenReturn(Optional.empty());var service=new RefreshTokenService(jwt,repository,mock(AuthPrincipalResolver.class),clock);assertThatThrownBy(()->service.refresh("token")).isInstanceOf(AuthProblemException.class).hasMessageContaining("Refresh token");} @Test void shouldRejectRevokedOrExpiredRefreshSession(){var jwt=mock(JwtTokenService.class);var repository=mock(RefreshTokenRepository.class);var session=mock(RefreshTokenSession.class);when(jwt.parseRefresh("token")).thenReturn(claims());when(repository.findByJti("jti-1")).thenReturn(Optional.of(session));when(session.getSubjectType()).thenReturn(SubjectType.PROFESSOR);when(session.getSubjectId()).thenReturn(10L);when(session.isActiveAt(NOW)).thenReturn(false);var service=new RefreshTokenService(jwt,repository,mock(AuthPrincipalResolver.class),clock);assertThatThrownBy(()->service.refresh("token")).isInstanceOf(AuthProblemException.class).hasMessageContaining("Refresh token");} @Test void shouldRotateValidRefreshSession(){var jwt=mock(JwtTokenService.class);var repository=mock(RefreshTokenRepository.class);var resolver=mock(AuthPrincipalResolver.class);var session=mock(RefreshTokenSession.class);var principal=new AuthPrincipal(10L,"Prof. Ana","ana@escola.com",SubjectType.PROFESSOR);when(jwt.parseRefresh("token")).thenReturn(claims());when(repository.findByJti("jti-1")).thenReturn(Optional.of(session));when(session.getSubjectType()).thenReturn(SubjectType.PROFESSOR);when(session.getSubjectId()).thenReturn(10L);when(session.isActiveAt(NOW)).thenReturn(true);when(resolver.resolve(SubjectType.PROFESSOR,10L)).thenReturn(principal);when(jwt.issueAccess(principal)).thenReturn(new JwtTokenService.TokenValue("access-2","a-2",NOW.plusSeconds(900)));when(jwt.issueRefresh(principal)).thenReturn(new JwtTokenService.TokenValue("refresh-2","r-2",NOW.plusSeconds(604800)));var service=new RefreshTokenService(jwt,repository,resolver,clock);var response=service.refresh("token");verify(session).revoke(NOW);verify(repository).save(any(RefreshTokenSession.class));assertThat(response.accessToken()).isEqualTo("access-2");assertThat(response.refreshToken()).isEqualTo("refresh-2");} @Test void shouldRejectAccessTokenUsedAsRefresh(){var jwt=mock(JwtTokenService.class);when(jwt.parseRefresh("access-token")).thenThrow(new IllegalArgumentException("Token is not a refresh token"));var service=new RefreshTokenService(jwt,mock(RefreshTokenRepository.class),mock(AuthPrincipalResolver.class),clock);assertThatThrownBy(()->service.refresh("access-token")).isInstanceOf(AuthProblemException.class).hasMessageContaining("Refresh token");} @Test void logoutShouldBeIdempotentForInvalidToken(){var jwt=mock(JwtTokenService.class);when(jwt.parseRefresh("bad-token")).thenThrow(new IllegalArgumentException("bad"));var service=new RefreshTokenService(jwt,mock(RefreshTokenRepository.class),mock(AuthPrincipalResolver.class),clock);assertThatCode(()->service.logout("bad-token")).doesNotThrowAnyException();} private JwtTokenService.RefreshTokenClaims claims(){return new JwtTokenService.RefreshTokenClaims("jti-1",SubjectType.PROFESSOR,10L,NOW.plusSeconds(3600));} }
